INSERT IGNORE INTO content_pages
  (content_item_id, standfirst_en, standfirst_ur, body_en, body_ur,
   hero_image_id)
SELECT ci.id, NULL, NULL, NULL, NULL, NULL
  FROM content_items ci
 WHERE ci.content_type = 'page'
   AND ci.slug IN ('news', 'news-press-releases', 'news-circulars', 'news-galleries', 'news-videos', 'news-media-contacts');

-- news-circulars  (/news/circulars)
--   from https://lcci.com.pk/business.php?id=88 (488 chars)
UPDATE content_pages p
  JOIN content_items ci ON ci.id = p.content_item_id
   SET p.body_en = '<h2>LCCI Circular</h2><p>Pakistan Halal Authority Survey Form</p>

<p>As a part of 3rd party evaluation on the directions of the right sizing committee government of Pakistan, the evaluator has required the feedback through a survey form link is attached here with. It will take hardly 4 to 5 minutes to submit. </p>

<p><a href="https://forms.gle/6ZgREe3JYpTux85z6">https://forms.gle/6ZgREe3JYpTux85z6</a></p>

<p> </p>

<p>Therefore, it is requested to fill the survey form at earliest.</p>

<p> </p>




<h4>Deputy Director (Coord.)</h4>

<h4>Pakistan Halal Authority</h4>

<h4>Ministry of Science &amp; Technology</h4>

<h4>Islamabad</h4>


<h4>Tel:0333-3645707</h4>

<p></p>'
 WHERE ci.content_type = 'page'
   AND ci.slug = 'news-circulars'
   AND p.body_en IS NULL;

UPDATE content_items
   SET status = 'published', published_at = '2026-10-01 05:00:00.000'
 WHERE content_type = 'page' AND slug = 'news-circulars'
   AND status = 'draft'
   AND EXISTS (
     SELECT 1 FROM content_pages p
      WHERE p.content_item_id = content_items.id AND p.body_en IS NOT NULL
   );

